// The FEATURE node projection (`a-feature-is-a-node`) — turn the plan's feature roster + its stream
// roster into Glance nodes and edges.
//
// The rosters come from `bsc plan feature list --json` and `bsc plan fleet get --full`. This module is
// the PURE projection of those into the graph vocabulary; fetching them is the caller's job, exactly
// as `surfaceNodes.ts` splits the crate roster from its projection.
//
// ONE NODE PER FEATURE, INCLUDING THE ONES WITH NO STREAMS. Same reasoning that gives a verb-less
// crate a node: a lane nobody has staffed is precisely the one worth seeing. Six of studio-code's 44
// features had no stream when this was written, and a projection that dropped them would have made
// the gap invisible in the one view that exists to show gaps.
import type { GlanceData } from "@/features/glance/lib/glanceData";
import {
  featureNodeId,
  featureRequiresNodeId,
  belongsToEdgeId,
  // The project→library `requires` edge id, reused rather than re-minted: a feature requiring a record
  // is the same relationship the L0 graph already draws, and a second id scheme for it would make the
  // same edge unequal to itself across the two views.
  requiresEdgeId,
  type GRawNode,
  type GRawEdge,
} from "@/features/glance/lib/glanceGraph";

/** One row of `bsc plan feature list --json`. */
export interface FeatureRow {
  slug: string;
  name?: string;
  /** The records this feature declares it needs. A bare id, or an entry carrying its provenance —
   *  the two shapes `RequiredRef` holds, and the reason the node can say WHO asked for a record. */
  requires?: Array<string | { id: string; by?: string; note?: string }>;
}

/** One row of the fleet's `streams` array, lean or full. */
export interface StreamRow {
  id: string;
  name?: string;
  /** `owner/name`, exactly as the plan records it. The fleet BANDS nodes by this
   *  (`withStreamRepos` → `glance-graph`), and a feature node that carries none lands in the
   *  unbanded group — which is how folding the streams away removed the repository separation. */
  repo?: string;
  /** Which feature it belongs to. ABSENT falls back to the stream's own id, which is how the 37
   *  streams whose id already IS a feature slug resolve — the same rule the launch applies, restated
   *  here rather than assumed, because a projection that disagreed with the launch would draw a graph
   *  of a fleet that does not exist. */
  feature?: string;
  kind?: string;
}

/** The projected band and its drill. */
export interface FeatureGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/** Which feature a stream belongs to — its own `feature`, else its id. See {@link StreamRow.feature}. */
export function streamFeature(s: StreamRow): string {
  const f = (s.feature ?? "").trim();
  return f || s.id;
}

/** The id of a required entry, whichever shape it takes. */
export function requiredId(r: string | { id: string }): string {
  return typeof r === "string" ? r : r.id;
}

/** Who asked for a required entry, when it says. A bare id carries no author — absent, never invented. */
export function requiredBy(r: string | { id: string; by?: string }): string | undefined {
  return typeof r === "string" ? undefined : r.by;
}

/** Every repo `slug` has streams in, in first-appearance order, and how many in each. */
function reposOf(streams: StreamRow[], slug: string): Map<string, number> {
  const out = new Map<string, number>();
  for (const s of streams) {
    if (streamFeature(s) !== slug) continue;
    const r = (s.repo ?? "").trim();
    if (r) out.set(r, (out.get(r) ?? 0) + 1);
  }
  return out;
}

/**
 * The repo a feature with NO streams bands under — the plan's dominant one.
 *
 * There is nothing on the feature itself to derive from, so this is a display default rather than a
 * claim about ownership. It is the right default because the alternative is what the maintainer
 * reported: an unbanded node sits LEFT of the repo fence with the director and the architect, so
 * `help` and `settings` read as project-level actors rather than as the unstaffed features they are.
 * Saying "probably the main repo" is a smaller error than saying "belongs to no repository".
 */
function dominantRepo(streams: StreamRow[]): string | undefined {
  const n = new Map<string, number>();
  for (const s of streams) {
    const r = (s.repo ?? "").trim();
    if (r) n.set(r, (n.get(r) ?? 0) + 1);
  }
  let best: string | undefined;
  for (const [r, c] of n) if (!best || c > (n.get(best) ?? 0)) best = r;
  return best;
}

/**
 * The FEATURE BAND — one node per feature, carrying how many streams it owns.
 *
 * The stream count rides on the node so the band answers "how big is this lane" without a drill. It is
 * the number a reader is actually scanning for: `teams-personas` owning 20 streams and `cad` owning one
 * are different kinds of thing, and a band of identically-sized cards would hide that.
 *
 * DETERMINISTIC — features in roster order, so two renders of the same plan diff meaningfully.
 */
export function featureBand(features: FeatureRow[], streams: StreamRow[]): FeatureGraph {
  const dominant = dominantRepo(streams);
  const nodes: GRawNode[] = features.flatMap((f) => {
    const repos = reposOf(streams, f.slug);
    // ONE NODE PER REPO THE FEATURE HAS WORK IN. A feature spanning repositories really does have work
    // in each, so a majority pick would erase the minority and leaving it unbanded would say it belongs
    // to none. `mobile-tunnel` is the live case: 1 stream in base-studio-code, 2 in mobile.
    //
    // The DUPLICATION IS SAFE because cross-repo coherence is not this graph's job — it is enforced
    // through the components and algorithms graphs and their relationships (maintainer, 2026-09-03).
    //
    // No streams at all ⇒ one node under the plan's dominant repo; see {@link dominantRepo}.
    const bands: { repo?: string; n: number }[] =
      repos.size > 0 ? [...repos].map(([repo, n]) => ({ repo, n })) : [{ repo: dominant, n: 0 }];
    return bands.map(({ repo, n }) => ({
      // The suffix ONLY when the feature actually spans, so the ids that already work do not churn.
      id: featureNodeId(f.slug, repos.size > 1 ? repo : undefined),
      slug: f.slug,
      kind: "feature" as const,
      // `service` — a feature is a CAPABILITY this product offers, which is the closest the role
      // vocabulary has. The size lives in `roleLabel` rather than in the colour.
      role: "service" as const,
      // Only THIS band's streams. A per-repo node claiming the whole feature's count would print the
      // same number in both bands, and neither would be checkable against what is under it.
      //
      // `0 streams` is stated rather than omitted: an unstaffed lane rendering as a blank card is
      // indistinguishable from a rendering bug.
      roleLabel: `${n} streams`,
      // THE REPO BAND, rebuilt on the coarse node. `withStreamRepos` stamps this per STREAM and the
      // layout bands by it, so a feature carrying none lands ungrouped beside the director — which is
      // exactly what removed the repository separation when the streams stopped being drawn.
      ...(repo ? { repo } : {}),
      health: "off" as const,
      activity: "idle" as const,
    }));
  });
  // The band draws no edges between features. `dependsOn` on a feature is the roadmap DAG — a
  // SEQUENCING hint, not a dependency the code has — and drawing it here would read as the same kind
  // of line the crate band uses for a real cargo edge.
  return { nodes, edges: [] };
}

/**
 * ONE FEATURE'S DRILL — its streams beneath it, and the records it requires beside them.
 *
 * Two node kinds because they answer two different questions. A STREAM is a lane of this project's own
 * work, with a worktree and a worker; a REQUIRED RECORD is something from the shared graphs this
 * feature builds against and does not own. Collapsing them would suggest a worker can edit both, and
 * the whole point of `requires` is that the second kind lives somewhere else.
 *
 * A required node names WHICH STORE answers it, because `bsc graph impl get` and `bsc ui get` are
 * different commands: a drill that guessed would send a reader to one that returns nothing for half
 * the list — the same reason the launch block resolves the store rather than assuming.
 */
export function featureDrill(
  feature: FeatureRow,
  streams: StreamRow[],
  /** Which store holds a record id, when known. `undefined` ⇒ the drill says so rather than guessing. */
  storeOf: (recordId: string) => "algorithms" | "components" | undefined = () => undefined,
): FeatureGraph {
  // THE FEATURE ITSELF IS THE ROOT OF ITS OWN DRILL, and it was missing. Every edge below names
  // `featureNodeId(feature.slug)`, so without this node the whole drill dangled: the streams rendered
  // with nothing to hang from, which is exactly what a reader sees as "no root".
  //
  // `featureBand` filters its edges to the nodes it emits (`known.has(e.from) && known.has(e.to)`);
  // this function had no such filter, so the dangling edges went straight into `buildGraph`. The band
  // was careful and the drill was not — hence `emitsNoDanglingEdge` in the tests, which asserts the
  // property for BOTH rather than trusting either.
  const nodes: GRawNode[] = [
    {
      id: featureNodeId(feature.slug),
      slug: feature.slug,
      kind: "feature" as const,
      role: "service" as const,
      roleLabel: `${streams.filter((s) => streamFeature(s) === feature.slug).length} streams`,
      health: "off" as const,
      activity: "idle" as const,
    },
  ];
  const edges: GRawEdge[] = [];

  const mine = streams.filter((s) => streamFeature(s) === feature.slug);
  for (const s of mine) {
    nodes.push({
      // THE STREAM'S OWN ID, which is the id the FLEET drill gives the same lane
      // (`glance-fleet.ts`: `nodeId: s.id`) — and panes bind as `fleetPaneId(drill, nodeId)`. Minting
      // `fstream:<feature>:<stream>` here gave one lane two identities depending on which graph you
      // arrived through, and only the fleet's resolved to a pane: the node said `session` and behaved
      // like a label. A worker's session must be the SAME session however the user navigated to it.
      id: s.id,
      slug: s.id,
      kind: "session" as const,
      // `client` — something that RUNS on its own, which is exactly what a stream is: a lane with a
      // worktree and a worker of its own.
      role: "client" as const,
      roleLabel: s.kind && s.kind !== "feature" ? s.kind : "stream",
      health: "off" as const,
      activity: "idle" as const,
    });
    edges.push({
      id: belongsToEdgeId(feature.slug, s.id),
      from: s.id,
      to: featureNodeId(feature.slug),
      kind: "belongs-to" as const,
    });
  }

  for (const r of feature.requires ?? []) {
    const id = requiredId(r);
    const store = storeOf(id);
    const by = requiredBy(r);
    nodes.push({
      id: featureRequiresNodeId(feature.slug, id),
      slug: id,
      kind: "library" as const,
      // `infra` — something others BUILD ON, the same role the crate band gives a library. A required
      // record is precisely that: shared, and not this feature's to edit.
      role: "infra" as const,
      // The store, then who asked. Both are facts a reader needs before acting: which command reads it,
      // and whether this entry was a director's seed or a worker's discovery.
      roleLabel: `${store ?? "unresolved"}${by ? ` · by ${by}` : ""}`,
      health: store ? ("off" as const) : ("warning" as const),
      // An id in NEITHER store is a dangling reference, and it is surfaced here rather than dropped —
      // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
      // places a typo can become visible.
      ...(store ? {} : { reason: "in neither graph" }),
      activity: "idle" as const,
    });
    edges.push({
      id: requiresEdgeId(feature.slug, featureRequiresNodeId(feature.slug, id)),
      from: featureNodeId(feature.slug),
      to: featureRequiresNodeId(feature.slug, id),
      kind: "requires" as const,
    });
  }
  return { nodes, edges };
}


/**
 * FOLD THE FEATURE BAND INTO A DRILL — the call site `featureBand` existed six hours without.
 *
 * `a-feature-is-a-node` shipped the projection with three passing tests and nothing calling it, so the
 * band did not exist in the running app and no gate could tell. That is the second time this repo has
 * done it — `glanceFoldsAreCalled.test.ts` was written the first time, and its header says the whole
 * thing: A GRAPH FOLD WITH NO CALLER IS A NODE NOBODY SEES.
 *
 * Shaped exactly like [`withSurfaceNodes`], because the constraints are the same ones:
 *
 * - EMPTY IN, UNCHANGED OUT. A project with no features must cost nothing, not an empty band.
 * - AN ID ALREADY PRESENT IS NOT RE-ADDED, so folding twice is folding once.
 * - AN EDGE SURVIVES ONLY IF BOTH ENDS RESOLVE. A feature node drawn under some other kind must not
 *   acquire a dangling line, and the drill is assembled from several folds in sequence.
 */
export function withFeatureNodes(
  data: GlanceData,
  features: FeatureRow[],
  streams: StreamRow[],
): GlanceData {
  if (!features.length) return data;
  const { nodes, edges } = featureBand(features, streams);

  // THE FEATURE REPLACES THE STREAMS IT COVERS — it does not sit on top of them.
  //
  // This fold used to only ADD, so `buildRealFleetData`'s 89 flat stream nodes stayed exactly where
  // they were and 27 feature cards rendered over them. Both plans on one canvas: the maintainer read
  // that as "I'm still seeing the old plan" four times across two days, and every fix in between —
  // the re-mapping, the band, the drill wiring, the missing root, the dropped `feature` field — was
  // real and none of them could have helped, because they made the NEW layer correct while the OLD
  // one kept drawing underneath.
  //
  // A stream a feature owns is reachable by drilling that feature (`featureDrill`), so drawing it
  // flat here says the coarse node is decoration rather than the level you navigate.
  const slugs = new Set(features.map((f) => f.slug));
  // stream id → the feature node standing for it. Also the redirect table below.
  const standsFor = new Map<string, string>();
  for (const s of streams) {
    const f = streamFeature(s);
    if (!slugs.has(f)) continue;
    // TO THE NODE FOR ITS OWN REPO. A spanning feature draws one node per band, so a mobile stream
    // must fold onto the mobile node and a desktop stream onto the desktop one — otherwise the
    // director's `manages` would all land on whichever band happened to be first, and the other band's
    // node would sit there unmanaged.
    const spans = reposOf(streams, f).size > 1;
    const repo = (s.repo ?? "").trim();
    standsFor.set(s.id, featureNodeId(f, spans && repo ? repo : undefined));
  }

  const present = new Set(data.rawNodes.map((n) => n.id));
  const add = nodes.filter((n) => !present.has(n.id));
  // Nothing to add AND nothing to remove ⇒ the graph is already what it should be.
  if (!add.length && !standsFor.size) return data;

  // A stream belonging to NO feature stays drawn. Removing it would hide unassigned work, which is
  // the one thing this view must never do — an unstaffed lane is exactly what a reader is scanning
  // for, and it would vanish with no node to notice it by.
  const keptNodes = data.rawNodes.filter((n) => !standsFor.has(n.id));
  const known = new Set([...keptNodes.map((n) => n.id), ...add.map((n) => n.id)]);

  // THE FEATURE INHERITS THE RELATIONSHIPS OF THE STREAMS IT STANDS FOR — it does not get a fresh
  // edge minted for it.
  //
  // `fleetToOrg` already draws `director manages <stream>` for every stream, through `archOf`, which
  // lets a TEAM author a different archetype for a persona pair. Minting a new `manages` edge here
  // would discard that authored value and quietly disagree with the team graph; redirecting keeps
  // whatever the edge actually said. It also generalises for free — anything that pointed at a
  // stream now points at its feature, without this fold needing to know who or why.
  const redirect = (id: string) => standsFor.get(id) ?? id;
  const rerouted: GRawEdge[] = [];
  const seenPair = new Set<string>();
  for (const e of data.rawEdges) {
    // A STREAM-TO-STREAM EDGE IS NOT A FEATURE-TO-FEATURE FACT, and folding it invents claims the
    // plan never made. MEASURED on studio-code: 208 `dependsOn` edges between streams, ZERO cycles
    // among them — and 20 cycles among features once folded (`cli-platform → cad → cli-platform`,
    // `planner → console → planner`, eighteen more). They flooded the coordination-hazard pane and
    // hid the list behind deadlocks that do not exist.
    //
    // Collapsing a DAG's nodes into groups manufactures cycles: one cli-platform stream depending on
    // a cad stream while some cad stream depends on a cli-platform one is perfectly acyclic at stream
    // level. `featureBand` had already ruled on this — "the band draws no edges between features,
    // `dependsOn` on a feature is a SEQUENCING hint, not a dependency the code has" — and folding
    // every edge reintroduced exactly what that forbids.
    //
    // So only edges from OUTSIDE the covered set fold: the director's `manages` becomes
    // `director manages <feature>`, while a stream's own dependency stays a stream's own business.
    if (standsFor.has(e.from) && standsFor.has(e.to)) continue;
    const from = redirect(e.from);
    const to = redirect(e.to);
    // A stream's own edge to its feature says nothing the containment does not.
    if (from === to) continue;
    if (!known.has(from) || !known.has(to)) continue;
    // N streams under one feature collapse to ONE edge. Twenty parallel `director manages` lines
    // between the same pair is the same fact drawn twenty times.
    const key = `${from}|${to}|${e.kind}`;
    if (seenPair.has(key)) continue;
    seenPair.add(key);
    rerouted.push(
      from === e.from && to === e.to ? e : { ...e, from, to, id: `${e.kind}:${from}>${to}` },
    );
  }

  const seen = new Set(rerouted.map((e) => e.id));
  const addEdges = edges.filter((e) => !seen.has(e.id) && known.has(e.from) && known.has(e.to));
  return { ...data, rawNodes: [...keptNodes, ...add], rawEdges: [...rerouted, ...addEdges] };
}

