// The FEATURE node projection (`a-feature-is-a-node`) — the band and one feature's drill.
import { describe, it, expect } from "vitest";
import { featureBand, featureDrill, withFeatureNodes, streamFeature, requiredId, requiredBy } from "@/features/glance/lib/featureNodes";
import { featureNodeId, featureRequiresNodeId } from "@/features/glance/lib/glanceGraph";

const FEATURES = [
  { slug: "glance", name: "Glance", requires: ["safe-invoke.ts", { id: "use-poll.ts", by: "director" }] },
  { slug: "cad", name: "CAD" },
  // No stream anywhere — the case the band must still show.
  { slug: "orphan", name: "Orphan" },
];
const STREAMS = [
  { id: "glance", repo: "o/r" },                              // id IS the slug — the fallback
  { id: "fleet-panes", feature: "glance", repo: "o/r" },       // explicitly under glance
  { id: "cad", feature: "cad", kind: "cleanup", repo: "o/r" },
];

describe("streamFeature — which feature a stream belongs to", () => {
  it("prefers the stream's own `feature` and falls back to its id", () => {
    // The fallback is not a convenience: 37 of studio-code's 89 stream ids ARE feature slugs and the
    // launch has always leaned on that. A projection that disagreed with the launch would draw a graph
    // of a fleet that does not exist.
    expect(streamFeature({ id: "fleet-panes", feature: "glance" })).toBe("glance");
    expect(streamFeature({ id: "glance" })).toBe("glance");
    // Whitespace is the shape a hand-edited record has; it must not read as a real feature.
    expect(streamFeature({ id: "glance", feature: "   " })).toBe("glance");
  });
});

describe("featureBand", () => {
  it("gives EVERY feature a node, including one with no streams", () => {
    // The same reasoning that gives a verb-less crate a node: an unstaffed lane is exactly the one
    // worth seeing, and a projection that dropped it would hide the gap in the view that exists to
    // show gaps.
    const { nodes } = featureBand(FEATURES, STREAMS);
    expect(nodes.map((n) => n.slug)).toEqual(["glance", "cad", "orphan"]);
    expect(nodes.map((n) => n.id)).toEqual([
      featureNodeId("glance"), featureNodeId("cad"), featureNodeId("orphan"),
    ]);
  });

  it("carries the stream COUNT, and states zero rather than omitting it", () => {
    const byId = new Map(featureBand(FEATURES, STREAMS).nodes.map((n) => [n.slug, n.roleLabel]));
    expect(byId.get("glance")).toBe("2 streams");   // the fallback one AND the explicit one
    expect(byId.get("cad")).toBe("1 streams");
    // A blank card is indistinguishable from a rendering bug; `0 streams` is a fact.
    expect(byId.get("orphan")).toBe("0 streams");
  });

  it("draws NO edges between features", () => {
    // `dependsOn` on a feature is the roadmap DAG — a sequencing hint, not a dependency the code has.
    // Drawing it here would read as the same kind of line the crate band uses for a real cargo edge.
    expect(featureBand(FEATURES, STREAMS).edges).toEqual([]);
  });

  it("is deterministic — roster order in, same order out", () => {
    const a = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    const b = featureBand(FEATURES, STREAMS).nodes.map((n) => n.id);
    expect(a).toEqual(b);
  });
});

describe("featureDrill", () => {
  const store = (id: string) => (id === "safe-invoke.ts" ? ("algorithms" as const) : undefined);

  it("puts this feature's streams beneath it, and no other feature's", () => {
    const { nodes, edges } = featureDrill(FEATURES[0], STREAMS, store);
    const streams = nodes.filter((n) => n.kind === "session").map((n) => n.slug);
    expect(streams).toEqual(["glance", "fleet-panes"]);
    expect(streams).not.toContain("cad");
    // Every stream edge points UP to the feature — the drill reads as one lane under one owner.
    const belongs = edges.filter((e) => e.kind === "belongs-to");
    expect(belongs).toHaveLength(2);
    expect(belongs.every((e) => e.to === featureNodeId("glance"))).toBe(true);
    // ONE IDENTITY PER STREAM. The node id is the STREAM's own id — the same id the fleet drill
    // gives the lane — so `fleetPaneId(drill, id)` finds the same pane and the node really is the
    // session it claims to be. A minted `fstream:…` id resolved to nothing.
    expect(belongs[0].from).toBe("glance");
    expect(nodes.filter((n) => n.kind === "session").map((n) => n.id)).toEqual(["glance", "fleet-panes"]);
  });

  it("keeps required RECORDS a different kind from streams", () => {
    // They answer different questions: a stream is this project's own work with a worktree and a
    // worker; a required record is shared and NOT this feature's to edit. Collapsing them would
    // suggest a worker can change both, which is the whole thing `requires` exists to deny.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const req = nodes.filter((n) => n.kind === "library");
    expect(req.map((n) => n.slug)).toEqual(["safe-invoke.ts", "use-poll.ts"]);
    expect(req.every((n) => n.role === "infra")).toBe(true);
  });

  it("names WHICH STORE answers a record, and who asked for it", () => {
    // `bsc graph impl get` and `bsc ui get` are different commands — a drill that guessed would send a
    // reader to one that returns nothing for half the list.
    const req = featureDrill(FEATURES[0], STREAMS, store).nodes.filter((n) => n.kind === "library");
    expect(req[0].roleLabel).toBe("algorithms");
    // …and the provenance rides along, which is the whole point of the attributed write.
    expect(req[1].roleLabel).toContain("by director");
  });

  it("flags a record in NEITHER graph rather than dropping it", () => {
    // `requires` is deliberately not validated at plan-write time, so a drill is one of the first
    // places a typo becomes visible. Silently omitting it would make a dangling id look like a
    // feature that requires less than it does.
    const dangling = featureDrill({ slug: "x", requires: ["nope.ts"] }, [], () => undefined);
    // FIND it rather than indexing: node 0 is the feature's own root now, and an index-based test
    // silently changes what it asserts the moment the node order does.
    const n = dangling.nodes.find((x) => x.id === featureRequiresNodeId("x", "nope.ts"))!;
    expect(n, "the dangling record was dropped instead of flagged").toBeDefined();
    expect(n.id).toBe(featureRequiresNodeId("x", "nope.ts"));
    expect(n.health).toBe("warning");
    expect(n.reason).toBe("in neither graph");
  });

  it("puts the FEATURE ITSELF in the graph — the root its streams hang from", () => {
    // It was missing, and every edge named it: the streams rendered with nothing to hang from, which
    // is what a reader sees as "no root". A projection that emits an edge to a node it does not emit
    // is broken however good its other nodes are.
    const { nodes } = featureDrill(FEATURES[0], STREAMS, store);
    const root = nodes.find((n) => n.id === featureNodeId("glance"));
    expect(root, "the drilled feature has no node of its own").toBeDefined();
    expect(root!.kind).toBe("feature");
    expect(root!.roleLabel).toBe("2 streams");
  });

  it("holds a feature with nothing under it to just its root, rather than throwing", () => {
    // Not `{nodes: [], edges: []}` any more: an unstaffed feature still IS one, and a drill that
    // rendered blank would be indistinguishable from a broken one.
    const { nodes, edges } = featureDrill(FEATURES[2], STREAMS, store);
    expect(nodes.map((n) => n.id)).toEqual([featureNodeId("orphan")]);
    expect(edges).toEqual([]);
  });

  // THE INVARIANT THAT WOULD HAVE CAUGHT IT, asserted over BOTH projections rather than trusting
  // either: `featureBand` filtered its edges to the nodes it emitted and `featureDrill` did not, so
  // the property held in one and silently failed in the other.
  it("emits no edge to a node it does not also emit", () => {
    for (const f of FEATURES) {
      const { nodes, edges } = featureDrill(f, STREAMS, store);
      const ids = new Set(nodes.map((n) => n.id));
      const dangling = edges.filter((e) => !ids.has(e.from) || !ids.has(e.to));
      expect(dangling.map((e) => e.id), `dangling edge(s) in the ${f.slug} drill`).toEqual([]);
    }
  });
});

describe("requiredId / requiredBy — the two entry shapes", () => {
  it("reads a bare id and an attributed entry the same way, and invents no author", () => {
    expect(requiredId("a.ts")).toBe("a.ts");
    expect(requiredId({ id: "b.ts" })).toBe("b.ts");
    // A bare id carries NO author — absent, never guessed, which is what makes a seeded entry
    // distinguishable from a discovered one.
    expect(requiredBy("a.ts")).toBeUndefined();
    expect(requiredBy({ id: "b.ts", by: "worker-A" })).toBe("worker-A");
  });
});

// THE FOLD ITSELF WAS UNTESTED, which is how it shipped ADDING to the graph instead of REPLACING in
// it — 89 flat stream nodes and 27 feature cards on one canvas, read (correctly) as "the old plan".
// `featureBand` and `featureDrill` each had their own passing tests throughout; nothing asserted what
// the fold did to the graph it was folding into.
describe("withFeatureNodes — the feature replaces the streams it covers", () => {
  const FLEET = {
    sample: false,
    rawNodes: [
      { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
      { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      { id: "unassigned", slug: "unassigned", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
    ],
    rawEdges: [
      { id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const },
      { id: "d-panes", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      { id: "d-un", from: "director", to: "unassigned", kind: "coordinates" as const },
    ],
  };
  const FEATS = [{ slug: "glance", name: "Glance" }];
  const STRS = [
    { id: "glance", feature: "glance" },
    { id: "fleet-panes", feature: "glance" },
    { id: "unassigned" },
  ];

  it("drops the stream nodes its features stand for", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = out.rawNodes.map((n) => n.id);
    expect(ids).not.toContain("glance");
    expect(ids).not.toContain("fleet-panes");
    expect(ids).toContain(featureNodeId("glance"));
  });

  it("KEEPS a stream no feature covers — unassigned work must not vanish", () => {
    // The one thing this view must never do. An unstaffed lane is exactly what a reader is scanning
    // for, and removing it leaves no node to notice its absence by.
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("unassigned");
  });

  it("leaves the director alone", () => {
    expect(withFeatureNodes(FLEET, FEATS, STRS).rawNodes.map((n) => n.id)).toContain("director");
  });

  it("leaves no edge pointing at a removed stream", () => {
    // A dangling edge is what made the feature DRILL render rootless; the fold must not reintroduce
    // the same class one level up.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    expect(out.rawEdges.filter((e) => !ids.has(e.from) || !ids.has(e.to))).toEqual([]);
  });

  it("REDIRECTS a removed stream's edges onto its feature — the director still manages it", () => {
    // The relationship is inherited, not minted: `fleetToOrg` draws `director manages <stream>` via
    // `archOf`, which a TEAM may have authored differently. A fresh edge here would discard that.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const toFeature = out.rawEdges.filter((e) => e.to === featureNodeId("glance"));
    expect(toFeature).toHaveLength(1);
    expect(toFeature[0].from).toBe("director");
    expect(toFeature[0].kind).toBe("coordinates");
  });

  it("collapses N streams under one feature into ONE edge", () => {
    // `glance` covers two streams, and the director managed both. Twenty parallel lines between the
    // same pair is one fact drawn twenty times.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const pairs = out.rawEdges.map((e) => `${e.from}|${e.to}|${e.kind}`);
    expect(new Set(pairs).size).toBe(pairs.length);
  });

  it("keeps an UNCOVERED stream's own edge untouched", () => {
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    expect(out.rawEdges.find((e) => e.to === "unassigned")?.id).toBe("d-un");
  });

  it("preserves an AUTHORED archetype through the redirect", () => {
    const authored = {
      ...FLEET,
      rawEdges: [{ id: "d-glance", from: "director", to: "glance", kind: "coordinates" as const, archetype: "mentors" }],
    };
    const out = withFeatureNodes(authored, FEATS, STRS);
    const e = out.rawEdges.find((x) => x.to === featureNodeId("glance"));
    expect(e?.archetype, "a team-authored archetype was replaced by a minted default").toBe("mentors");
  });

  it("does NOT fold a stream-to-stream edge into a feature-to-feature one", () => {
    // THE CYCLE FACTORY. Collapsing a DAG's nodes into groups manufactures cycles: MEASURED on the
    // real plan, 208 acyclic `dependsOn` edges between streams became 20 cycles between features,
    // which flooded the coordination-hazard pane and hid the list. The claims were invented — the
    // plan never said `cad` depends on `cli-platform`.
    const cross = {
      ...FLEET,
      rawNodes: [
        ...FLEET.rawNodes,
        { id: "cad", slug: "cad", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [{ id: "s-s", from: "glance", to: "cad", kind: "depends-on" as const }],
    };
    const out = withFeatureNodes(cross, [...FEATS, { slug: "cad", name: "CAD" }], [...STRS, { id: "cad", feature: "cad" }]);
    const featIds = new Set([featureNodeId("glance"), featureNodeId("cad")]);
    expect(
      out.rawEdges.filter((e) => featIds.has(e.from) && featIds.has(e.to)),
      "a stream's dependency was folded into a claim about features",
    ).toEqual([]);
  });

  it("carries the repo when its streams agree — the band survives the fold", () => {
    // `withStreamRepos` stamps this per STREAM and the layout bands by it. A feature carrying none
    // lands unbanded, which is how folding the streams away removed the repository separation.
    const withRepos = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/desktop" },
      { id: "unassigned" },
    ];
    const { nodes } = featureBand(FEATS, withRepos);
    expect(nodes.find((n) => n.slug === "glance")?.repo).toBe("o/desktop");
  });

  it("draws ONE NODE PER REPO when its streams span", () => {
    // A majority pick erases the minority; unbanded says it belongs to no repository at all. The
    // feature really does have work in both, so it appears in both bands. `mobile-tunnel` is the live
    // case. Safe to duplicate because cross-repo coherence is enforced through the components and
    // algorithms graphs, not here.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
      { id: "extra", feature: "glance", repo: "o/mobile" },
    ];
    const mine = featureBand(FEATS, spanning).nodes.filter((n) => n.slug === "glance");
    expect(mine.map((n) => n.repo).sort()).toEqual(["o/desktop", "o/mobile"]);
    expect(mine.map((n) => n.id).sort()).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
    // Each band counts ONLY its own streams — the same number in both would be uncheckable.
    expect(mine.find((n) => n.repo === "o/desktop")?.roleLabel).toBe("1 streams");
    expect(mine.find((n) => n.repo === "o/mobile")?.roleLabel).toBe("2 streams");
  });

  it("keeps the plain id for a single-repo feature — no churn", () => {
    const one = [{ id: "glance", feature: "glance", repo: "o/desktop" }];
    expect(featureBand(FEATS, one).nodes[0].id).toBe(featureNodeId("glance"));
  });

  it("bands a feature with NO streams under the plan's dominant repo", () => {
    // Floating beside the director made `help` and `settings` read as project-level actors rather
    // than the unstaffed features they are. "Probably the main repo" is the smaller error.
    const streams = [
      { id: "a", feature: "other", repo: "o/desktop" },
      { id: "b", feature: "other", repo: "o/desktop" },
      { id: "c", feature: "other", repo: "o/mobile" },
    ];
    const n = featureBand([{ slug: "help", name: "help" }], streams).nodes[0];
    expect(n.repo).toBe("o/desktop");
    expect(n.roleLabel).toBe("0 streams");
  });

  it("folds each stream onto the node for ITS OWN repo", () => {
    // Otherwise every `manages` edge lands on whichever band came first and the other sits unmanaged.
    const spanning = [
      { id: "glance", feature: "glance", repo: "o/desktop" },
      { id: "fleet-panes", feature: "glance", repo: "o/mobile" },
    ];
    const fleet = {
      sample: false,
      rawNodes: [
        { id: "director", slug: "director", kind: "session" as const, role: "service" as const, health: "off" as const, activity: "idle" as const },
        { id: "glance", slug: "glance", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
        { id: "fleet-panes", slug: "fleet-panes", kind: "session" as const, role: "client" as const, health: "off" as const, activity: "idle" as const },
      ],
      rawEdges: [
        { id: "d1", from: "director", to: "glance", kind: "coordinates" as const },
        { id: "d2", from: "director", to: "fleet-panes", kind: "coordinates" as const },
      ],
    };
    const out = withFeatureNodes(fleet, FEATS, spanning);
    const managed = out.rawEdges.filter((e) => e.from === "director").map((e) => e.to).sort();
    expect(managed).toEqual([
      featureNodeId("glance", "o/desktop"),
      featureNodeId("glance", "o/mobile"),
    ]);
  });

  it("draws no self-edge when two streams of one feature were connected", () => {
    const linked = {
      ...FLEET,
      rawEdges: [{ id: "s-s", from: "glance", to: "fleet-panes", kind: "coordinates" as const }],
    };
    const out = withFeatureNodes(linked, FEATS, STRS);
    expect(out.rawEdges.filter((e) => e.from === e.to)).toEqual([]);
  });

  it("never leaves a feature AND the streams it covers in one graph", () => {
    // THE INVARIANT, stated directly: two representations of the same work on one canvas is the bug.
    const out = withFeatureNodes(FLEET, FEATS, STRS);
    const ids = new Set(out.rawNodes.map((n) => n.id));
    for (const f of FEATS) {
      if (!ids.has(featureNodeId(f.slug))) continue;
      const covered = STRS.filter((s) => streamFeature(s) === f.slug).map((s) => s.id);
      expect(covered.filter((id) => ids.has(id)), `${f.slug} is drawn AND so are its streams`).toEqual([]);
    }
  });

  it("is a no-op with no features, rather than emptying the graph", () => {
    expect(withFeatureNodes(FLEET, [], STRS)).toBe(FLEET);
  });
});
